(() => {
  'use strict';
  const RELEASE='20261009maci1', STORE='quest360-maci-workspace-v1';
  const M=window.QuestMaciModel;
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const link=(url,label)=>/^(https?:\/\/|data\/)/.test(String(url||''))?`<a href="${esc(String(url).startsWith('data/')?'https://atanubarik.github.io/quest-intelligence-360/'+url:url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
  const session=()=>{try{return JSON.parse(sessionStorage.getItem('quest360-session-v2'))||{};}catch{return {};}};
  const enabled=()=>window.QuestWorkspaces?.ready()&&['maci','executive'].includes(session().team);
  const can=action=>enabled()&&M.can(session().role,action);
  let raw, model, pending, queued=false, sequence=0, lastResult=null;
  function state(){try{const s=JSON.parse(localStorage.getItem(STORE));return {requests:Array.isArray(s?.requests)?s.requests:[],evidence:Array.isArray(s?.evidence)?s.evidence:[]};}catch{return {requests:[],evidence:[]};}}
  function save(s){localStorage.setItem(STORE,JSON.stringify(s));model=M.build(raw,s.evidence);}
  const uid=()=>window.crypto?.randomUUID?.()||'maci-'+Date.now()+'-'+Math.random().toString(36).slice(2);
  const options=(items,value='')=>items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}"${v===value?' selected':''}>${esc(l)}</option>`;}).join('');
  const studyOptions=()=>model.studies.map(p=>[p.id,p.short_name]);
  const empty=text=>`<div class="qm-empty">${esc(text)}</div>`;
  const tag=(text,kind='')=>`<span class="qm-tag ${kind}">${esc(text)}</span>`;
  const note=text=>`<p class="qm-note">${esc(text)}</p>`;
  const button=(text,action,extra='',disabled=false)=>`<button type="button" data-qm-action="${action}" ${extra}${disabled?' disabled':''}>${esc(text)}</button>`;
  function sourceCard(s){return `<article class="qm-source" data-source-id="${esc(s.id)}"><div>${tag(s.kind)} ${tag(s.authority,'soft')}</div><h4>${link(s.url,s.title)}</h4><p>${esc(s.summary)}</p><dl><dt>Population / geography</dt><dd>${esc(s.population)} · ${esc(s.geography)}</dd><dt>Method / period</dt><dd>${esc(s.method)} · ${esc(s.collection_period)}</dd><dt>Sample</dt><dd>${esc(s.sample)}</dd></dl><p class="qm-note"><b>Limits:</b> ${esc(s.limitations)}</p><small>Published ${esc(s.published||'date not supplied')} · Reviewed ${esc(s.reviewed_at)} · ${esc(s.id)}</small></article>`;}
  function stats(s){return (s.statistics||[]).map(x=>`<div class="qm-stat-row"><div><span>${esc(x.label)}</span><strong>${esc(x.value)}%</strong></div><div class="qm-track" role="img" aria-label="${esc(x.label)}: ${esc(x.value)} percent; ${esc(x.base)}"><i style="width:${Math.max(0,Math.min(100,Number(x.value)))}%"></i></div><small>${esc(x.count===null?'':x.count+' / ')}${esc(x.base)}</small></div>`).join('');}
  async function load(){
    if(model)return model;if(pending)return pending;
    const task=window.QuestExperience?.start('Loading research context',6);let done=0;
    pending=Promise.all(['maci-research-context','project-tracker','pmr-repository-dashboard','pmr-insight-library','voice-experts-analysis','survey-analytics-demo'].map(async f=>{const r=await fetch(`data/${f}.json?v=${RELEASE}`);if(!r.ok)throw new Error(`Research file unavailable: ${f}`);const j=await r.json();window.QuestExperience?.step(task,++done);return j;})).then(([context,tracker,pmr,insights,voe,survey])=>{raw={context,tracker,pmr,insights,voe,survey};model=M.build(raw,state().evidence);return model;}).catch(e=>{pending=null;throw e;}).finally(()=>window.QuestExperience?.finish(task));return pending;
  }
  function portfolio(){
    const rows=model.studies, completed=rows.filter(p=>p.delivery.length&&p.delivery.every(t=>t.status==='Completed'));
    return `<div class="qm-section-head"><div><span class="qm-eyebrow">A / RESEARCH PORTFOLIO</span><h2>Research in motion</h2><p>Delivery context, study ownership and the questions behind each workstream.</p></div>${button('Open full project library','go','data-route="pmr"')}</div><div class="qm-metrics">${[[rows.length-completed.length,'Active studies','Recorded tracker status'],[completed.length,'Completed studies','Completed in source tracker'],[0,'Planned studies','No approved plan supplied'],[state().requests.filter(r=>r.status==='New').length,'New requests','Saved on this device']].map(([n,l,d])=>`<article><small>${esc(l)}</small><strong>${n}</strong><span>${esc(d)}</span></article>`).join('')}</div>${note('Tracker reporting date: '+model.tracker_date+'. Past milestone dates are retained as recorded; delivery status needs a current owner review. Proposed research below is not a committed study plan.')}<div class="qm-table-wrap"><table><thead><tr><th>Study / objective</th><th>Owner / sponsor contact</th><th>Method / stage</th><th>Milestone / deliverable</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.short_name)}</strong><p>${esc(p.objective)}</p></td><td>${esc(p.owner)}<p>${esc(p.sponsor_contacts)}</p><small>Business-unit sponsor: not recorded</small></td><td>${p.delivery.map(t=>`${esc(t.research_type)} · ${esc(t.status)}<br>`).join('')}</td><td>${p.delivery.map(t=>`<strong>${esc(t.milestone_due||'No due date recorded')}</strong><p>${esc(t.next_milestone||'No milestone recorded')}</p><small>Final: ${esc(t.final_status)} (${Number(t.final_progress)||0}%)</small>`).join('<hr>')}</td></tr>`).join('')}</tbody></table></div><details class="qm-card"><summary>Planned research / proposed agenda</summary><p>No commissioned future-study plan is supplied. These questions are proposed for an existing-evidence review before new fieldwork.</p><div class="qm-grid">${model.context.topics.map(t=>`<article class="qm-card"><h4>${esc(t.name)}</h4>${tag('Proposed; not commissioned')}<p>${esc(t.next_question)}</p><p>${esc(t.next_method)}</p><small>Owner: unassigned · Sponsor unit: not recorded · Milestone: not set</small>${button('Draft request','new-request','data-question="'+esc(t.next_question)+'"',!can('request'))}</article>`).join('')}</div></details>`;
  }
  function requests(){const s=state();return `<div class="qm-section-head"><div><span class="qm-eyebrow">B / RESEARCH REQUESTS</span><h2>Reuse first. Research the remaining gap.</h2><p>Check for existing evidence before commissioning a study.</p></div>${button('New research request','new-request','',!can('request'))}</div>${note('Requests and approvals are saved on this device. Hub Owners move requests through review; Contributors submit requests; Viewers read and export. No request is sent to another person.')}<div class="qm-board">${model.context.request_statuses.map(status=>`<section><h3>${esc(status)} <span>${s.requests.filter(r=>r.status===status).length}</span></h3>${s.requests.filter(r=>r.status===status).map(r=>`<details class="qm-request"><summary>${esc(r.question)}<small>${esc(r.priority)} priority · ${esc(r.customer)}</small></summary><dl>${[['Requestor',r.requestor],['Team',r.team],['Decision to support',r.decision],['Customer group',r.customer],['Geography',r.geography],['Desired deadline',r.deadline||'No deadline set'],['Owner',r.owner],['Existing evidence',r.existing],['Potential overlap',r.overlap],['Research gap',r.gap]].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v||'Not supplied')}</dd>`).join('')}</dl>${can('status')?`<label>Review status<select data-qm-request-status="${esc(r.id)}">${options(model.context.request_statuses,r.status)}</select></label>`:''}${button('Review relevant evidence','ask','data-question="'+esc(r.question)+'"')}</details>`).join('')||'<small>No requests</small>'}</section>`).join('')}</div><div data-qm-form-host="request"></div>`;}
  function pulse(){return `<div class="qm-section-head"><div><span class="qm-eyebrow">C / CUSTOMER INSIGHTS PULSE</span><h2>Know the customer. Keep the evidence.</h2><p>Public context opens a research question; approved customer evidence answers it.</p></div>${button('Add evidence record','new-evidence','',!can('evidence'))}</div><div class="qm-pulse">${['Needs','Experience','Perception'].map(pillar=>`<article><span class="qm-pillar">${esc(pillar)}</span><p class="qm-note">${esc({Needs:'Customer needs · Unmet needs · Pain points · Preferences · Expectations · Purchase drivers · Switching factors · Adoption barriers',Experience:'Journey pain points · Service experiences · Digital experiences · Communication experiences · Workflow friction · Satisfaction drivers',Perception:'Quest perceptions · Competitor perceptions · Product / service perceptions · Brand associations'}[pillar])}</p>${model.context.topics.filter(t=>t.pillar===pillar).map(t=>{const h=M.health(model).coverage.find(x=>x.topic.id===t.id);return `<details><summary>${esc(t.name)}<small>${h.approved_count} approved excerpts · ${h.public_count} public studies</small></summary><h4>Available evidence</h4>${model.approved.filter(r=>r.topic===t.id).slice(0,3).map(r=>`<p>${tag('Approved locally')} ${esc(r.summary)}<small>${esc(r.segment)} · ${esc(r.locator)} · ${esc(r.id)}</small></p>`).join('')}${model.public.filter(s=>s.topics.includes(t.id)&&s.kind!=='Supplier description').slice(0,2).map(s=>`<p>${tag('Public context')} ${esc(s.summary)}<small>${esc(s.geography)} · ${esc(s.sample)} · ${link(s.url,s.title)}</small></p>`).join('')||(!h.approved_count?note('No customer finding is established in the approved evidence supplied. Supplier descriptions, where available, remain market context.'):'')}<p><b>Research next:</b> ${esc(t.next_question)}</p><p>${esc(t.next_method)}</p>${button('Explore this evidence','ask','data-question="'+esc(t.name)+'"')}${button('Draft request','new-request','data-question="'+esc(t.next_question)+'"',!can('request'))}</details>`;}).join('')}</article>`).join('')}</div><div class="qm-evidence-banner"><strong>${model.approved.length} approved customer excerpts available</strong><p>The existing PMR findings and expert paraphrases are illustrative. Survey answers are synthetic. They remain available in the original modules, with their demo labels, and are excluded from the Research Partner’s default answers.</p></div><div data-qm-form-host="evidence"></div>${localEvidence()}`;}
  function localEvidence(){return state().evidence.length?`<details class="qm-local"><summary>Evidence review queue · ${state().evidence.length} records</summary>${state().evidence.map(r=>`<article class="qm-local-record"><h4>${esc(r.title)} ${tag(r.status)}</h4><p>${esc(r.summary)}</p><p>${esc(r.segment)} · ${esc(r.geography)} · ${esc(r.period)} · ${esc(r.method)}</p><p>${link(r.source,r.source)} · ${esc(r.locator)}</p><small>Limits: ${esc(r.limitations)}</small>${can('approve')&&r.status==='Pending Review'?`<div class="qm-actions">${button('Approve evidence','approve-evidence','data-id="'+esc(r.id)+'"')}${button('Return for revision','return-evidence','data-id="'+esc(r.id)+'"')}</div>`:''}</article>`).join('')}</details>`:'';}
  function evidenceHealth(project='all'){
    const h=M.health(model,project);
    return `<div class="qm-section-head"><div><span class="qm-eyebrow">D / RESEARCH EVIDENCE HEALTH</span><h2>What is well covered—and what is missing?</h2><p>Public research coverage and approved Quest evidence are assessed separately.</p></div></div><div class="qm-table-wrap"><table><thead><tr><th>Topic</th><th>Public context</th><th>Approved customer evidence</th><th>Next evidence need</th></tr></thead><tbody>${h.coverage.map(x=>`<tr><td><strong>${esc(x.topic.name)}</strong></td><td>${tag(x.level,x.public_count>=2?'good':'warm')}<small>${x.public_count} independent public study / review sources</small></td><td>${x.approved_count} excerpts<small>${esc(x.missing_segments)}<br>${esc(x.missing_geographies)}<br>${esc(x.missing_stakeholders)}</small></td><td>${x.needs_quant?'Quantitative validation<br>':''}${x.needs_qual?'Qualitative exploration':''}<small>Evidence counts do not establish study quality or sufficiency.</small></td></tr>`).join('')}</tbody></table></div><div class="qm-grid"> <article class="qm-card"><h3>Age review</h3>${note('Review threshold: '+model.context.policy.age_review_months+' months since fieldwork or publication where fieldwork is unavailable. Age alone does not invalidate a study.')}${h.aged.map(s=>`<p>${link(s.url,s.title)}<small>${esc(s.collection_period)} · ${esc(s.age_basis)} · review current applicability</small></p>`).join('')||empty('No dated source crosses the review threshold.')}</article><article class="qm-card"><h3>Contradictions & comparability</h3>${h.conflicts.length?h.conflicts.map(([a,b])=>`<p>${esc(a.title)} / ${esc(b.title)}: opposing coded positions on the same question and context. Owner review required.</p>`).join(''):note('No contradictory pair is established in the approved customer evidence supplied. Different populations, measures or methods are not automatically contradictions.')}<details><summary>Differences that need context</summary>${model.context.comparability_notes.map(n=>`<h4>${esc(n.title)}</h4><p>${esc(n.reason)}</p>`).join('')}</details></article></div>${h.inconsistent.map(i=>`<p class="qm-notice"><b>Metadata check:</b> ${esc(i.message)}</p>`).join('')}`;
  }
  function alerts(){const s=state(), h=M.health(model);const rows=[...model.studies.filter(p=>p.delivery.length&&p.delivery.every(t=>t.status==='Completed')).map(p=>['Study completed (recorded)',p.short_name+' · Tracker reporting date '+model.tracker_date]),...s.evidence.filter(r=>r.status==='Approved'&&r.deliverable==='Survey results').map(r=>['Survey results available',r.title]),...s.evidence.filter(r=>r.status==='Approved'&&r.deliverable==='Interview analysis').map(r=>['Interview analysis available',r.title]),...s.requests.filter(r=>r.status==='New').map(r=>['New research request',r.question]),...s.requests.filter(r=>r.status==='Completed').map(r=>['Request completed',r.question]),...s.evidence.filter(r=>r.status==='Pending Review').map(r=>['Approval required',r.title]),...s.evidence.filter(r=>r.status==='Approved').map(r=>['Evidence added',r.title]),...h.aged.map(x=>['Age review due',x.title]),...h.inconsistent.map(x=>['Tracker metadata check',x.message]),...h.conflicts.map(([a,b])=>['Contradiction review',a.title+' / '+b.title])];
    s.requests.forEach(r=>{const o=M.overlap(model,r.question,s.requests.filter(x=>x.id!==r.id));if(o.studies.length||o.requests.length)rows.push(['Potential research overlap',r.question+' · '+o.studies.length+' related studies; '+o.requests.length+' related requests. Review before calling this a duplicate.']);});
    return `<div class="qm-section-head"><div><span class="qm-eyebrow">E / MACI ALERTS</span><h2>Research signals that need attention</h2><p>Evidence changes and review cues from this workspace.</p></div></div><div class="qm-alerts">${rows.map(([t,b])=>`<article><span class="qm-alert-dot"></span><div><strong>${esc(t)}</strong><p>${esc(b)}</p></div></article>`).join('')}</div><details class="qm-card"><summary>Available feeds & missing events</summary><p>Survey results, interview analysis and completed-study alerts require dated approved deliverables. None are supplied as a live event feed, so this workspace does not claim those events occurred.</p><p><b>Market context linked to research:</b> Quest, Visiun, ARUP and Mayo public service descriptions are linked to interoperability, workflow and stewardship questions. Reviewed ${esc(model.context.reviewed_at)}; review date does not mean a product launched on that date.</p></details>`;
  }
  function renderHub(view){if(!view)return;if(!model){view.innerHTML='<div class="qm-center qm-loading" role="status">Loading research portfolio and evidence context…</div>';load().then(()=>{if(enabled())renderAll(true);}).catch(()=>{view.innerHTML='<div class="qm-center">Research context could not be loaded. '+button('Retry','retry')+'</div>';});return;}
    const current=view.querySelector('.qm-tabs [aria-selected="true"]')?.dataset.qmTab||'portfolio';
    view.innerHTML=`<div class="qm-center" data-qm-hub><header class="qm-hero"><div><span class="qm-eyebrow">MY HUB / MACI</span><h1>Research & Customer<br>Intelligence Center</h1><p>What do we know? What supports it? What exists already? What is missing—and what should we research next?</p><div class="qm-hero-tags">${tag(session().role)} ${tag('Curated for Market & Customer Insights')} ${tag('Reviewed '+model.context.reviewed_at)}</div></div><div class="qm-hero-orbit" aria-hidden="true"><span>QUESTION</span><i>◎</i><span>EVIDENCE → INSIGHT</span></div></header><div class="qm-actions qm-top-actions">${button('Ask Research Partner','go','data-route="copilot"')}${button('Primary Market Research','go','data-route="pmr"')}${button('Customer perception context','go','data-route="competitors"')}</div><div class="qm-tabs" role="tablist" aria-label="Research center sections">${[['portfolio','Research Portfolio'],['requests','Research Requests'],['pulse','Customer Insights Pulse'],['health','Evidence Health'],['alerts','MACI Alerts']].map(([id,l])=>`<button type="button" role="tab" id="qm-tab-${id}" aria-controls="qm-pane-${id}" aria-selected="${id===current}" tabindex="${id===current?0:-1}" data-qm-tab="${id}">${esc(l)}</button>`).join('')}</div>${[['portfolio',portfolio],['requests',requests],['pulse',pulse],['health',evidenceHealth],['alerts',alerts]].map(([id,fn])=>`<section class="qm-pane" role="tabpanel" tabindex="0" id="qm-pane-${id}" aria-labelledby="qm-tab-${id}"${id===current?'':' hidden'}>${fn()}</section>`).join('')}<footer class="qm-footer">Reviewed public context ≠ approved Quest customer research. Local excerpts retain their source and approval state. ${link(model.context.methodology_source,'Research disclosure guide')}</footer></div>`;
    window.QuestExperience?.enter(view.querySelector('.qm-center'));
  }
  function projectLibrary(){return `<div class="qm-section-head"><div><span class="qm-eyebrow">MACI / FULL STUDY CONTEXT</span><h2>Project Library</h2><p>Business questions, methods and source locations stay attached to each study.</p></div>${button('Download portfolio CSV','portfolio-export')}</div><div class="qm-library">${model.studies.map(p=>`<details class="qm-card"><summary>${esc(p.short_name)} ${tag(p.status_source)}<small>${esc(p.owner)} · ${esc(p.research_types.join(' / '))}</small></summary><p>${esc(p.objective)}</p><dl>${[['Business unit / sponsor',p.business_unit],['Sponsor contact(s)',p.sponsor_contacts],['Research owner',p.owner],['Vendor',p.vendor],['Research type / methodology',p.research_types.join('; ')+'; recruitment and analysis details not supplied'],['Target audience / segments',p.themes.join('; ')+' (topic mapping; approved sample-segment metadata not supplied)'],['Geography',p.geography],['Year / collection dates',p.delivery.map(t=>t.start_date||'Not recorded').join('; ')+' (start dates, not confirmed fieldwork periods)'],['Sample information',p.delivery.map(t=>`${t.research_type}: ${t.completed??'not recorded'} completed / ${t.total_target??'not recorded'} target`).join('; ')],['Project status',p.status_source],['Final deliverables',p.delivery.map(t=>t.final_status+'; final-output progress '+t.final_progress+'%').join('; ')],['Source location','Public delivery metadata: data/project-tracker.json. Confidential report/transcript locations and approvals not supplied.']].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h4>Proposed KBQ mapping</h4>${note('Analyst-authored questions based on recorded objectives. Confirm against the original brief before treating them as the study instrument.')}<ul>${p.proposed_kbqs.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><div class="qm-actions">${button('Find related evidence','ask','data-project="'+p.id+'" data-question="'+esc(p.short_name+' evidence')+'"')}${link(p.source,'Source metadata')}</div><p class="qm-note">Existing synthesis and artifact counts below remain a demo mapping; file counts do not prove that approved evidence is accessible.</p></details>`).join('')}</div><div class="qm-divider"></div>${crossProject()}<div class="qm-divider"></div>${reportControls()}`;}
  function crossProject(){return `<h2>Cross-Project Intelligence</h2><p>Compare research coverage without combining incompatible samples.</p><div class="qm-filter-row"><label>Comparison dimension<select data-qm-compare>${options(['Themes','Projects','Customer segments / personas','Geographies','Years','Research methodologies'])}</select></label><label>Study scope<select data-qm-compare-project>${options([['all','All MACI studies'],...studyOptions()])}</select></label></div><div data-qm-comparison>${comparison('Themes','all')}</div>${note('A shared theme is a reuse opportunity, not a pooled estimate. Survey question wording, population, base, period and method must align before numerical comparison.')}`;}
  function comparison(dimension,project){const studies=model.studies.filter(p=>project==='all'||p.id===project);if(dimension==='Themes')return `<div class="qm-table-wrap"><table><thead><tr><th>Theme</th>${studies.map(p=>`<th>${esc(p.short_name)}</th>`).join('')}</tr></thead><tbody>${model.context.topics.filter(t=>studies.some(p=>t.projects.includes(p.id))).map(t=>`<tr><th>${esc(t.name)}</th>${studies.map(p=>`<td>${t.projects.includes(p.id)?`${model.approved.filter(r=>r.project===p.id&&r.topic===t.id).length} approved excerpts<br><small>Proposed topic match; demo synthesis available</small>`:'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
    const key=dimension==='Geographies'?'geography':dimension==='Research methodologies'?'research_types':null;
    return `<div class="qm-table-wrap"><table><thead><tr><th>Project</th><th>${esc(dimension)}</th><th>Comparability limit</th></tr></thead><tbody>${studies.map(p=>{const v=key?Array.isArray(p[key])?p[key].join('; '):p[key]:dimension==='Years'?p.delivery.map(t=>t.start_date?.slice(0,4)||'Not recorded').join('; '):dimension==='Customer segments / personas'?(model.voe.segments||[]).filter(s=>s.observations.some(o=>o.project_id===p.id)).map(s=>s.persona).join('; '):p.objective;return `<tr><td>${esc(p.short_name)}</td><td>${esc(v||'Not recorded')}</td><td>${dimension==='Customer segments / personas'?'Illustrative personas; actual sample breakdown missing':dimension==='Years'?'Start year does not confirm fieldwork period':'Methods, geography and study base are not harmonized.'}</td></tr>`;}).join('')}</tbody></table></div>`;
  }
  function surveyPanel(){return `<div class="qm-section-head"><div><span class="qm-eyebrow">MACI / SURVEY EVIDENCE</span><h2>Questions, distributions & segment bases</h2><p>Published response categories are shown only when the source provides them.</p></div></div><div class="qm-filter-row"><label>Public study<select data-qm-survey-source>${options(model.public.filter(s=>s.statistics.length).map(s=>[s.id,s.title]))}</select></label></div><div data-qm-survey-chart>${surveyChart(model.public.find(s=>s.statistics.length).id)}</div><details class="qm-card"><summary>Existing survey question catalogue · ${model.survey.questions.length} demo metrics</summary>${note('The repository has synthetic cohort means, not respondent-level answers, original wording or distributions. No distributions, statistical significance, geographic splits or verbatim open-ended responses are reconstructed.')}<div class="qm-table-wrap"><table><thead><tr><th>Question / metric label</th><th>Scale / theme</th><th>Instrument availability</th></tr></thead><tbody>${model.survey.questions.map(q=>`<tr><td>${esc(q.label)}<small>${esc(q.key)}</small></td><td>${esc(q.scale)} · ${esc(q.theme)}</td><td>Original wording, answer options, missing-response base and weighting not supplied</td></tr>`).join('')}</tbody></table></div><h4>Measures to add when approved data are available</h4><div class="qm-chip-list">${model.context.survey_measures.map(x=>tag(x)).join('')}</div><p>Segment, geography and customer-type comparisons need actual subgroup membership and question-level bases. The digital-journey total of 100 is tracker-backed; its persona splits and answers are synthetic.</p></details><div class="qm-actions">${button('Survey Findings Report','report-direct','data-report="Survey Findings Report"')}${button('Cross-Tab Report','report-direct','data-report="Cross-Tab Report"')}</div>`;}
  function surveyChart(id){const s=model.public.find(x=>x.id===id);if(!s)return '';return `<div class="qm-grid"><article class="qm-card"><h3>${esc(s.title)}</h3>${stats(s)}${note(id==='jama-results-2023'?'Only yes/no/other form a response distribution; rounding totals 100.1%. Worry percentages are separate subgroup measures.':'These are separate published measures with their stated bases, not one response distribution.')}</article>${sourceCard(s)}</div>`;}
  function expertsPanel(){const qual=model.public.filter(s=>['Qualitative','Mixed methods'].includes(s.kind));return `<div class="qm-section-head"><div><span class="qm-eyebrow">MACI / VOICE OF EXPERTS</span><h2>Expert context and supporting evidence</h2><p>Interpret themes without losing stakeholder, method or geography.</p></div></div><div class="qm-grid">${qual.map(sourceCard).join('')}</div><h3>Cross-expert research lens</h3><div class="qm-filter-row"><label>View<select data-qm-expert-view>${options(['Plain Text','Consensus','Disagreement','Segment differences','Outliers','Emerging themes','Evidence gaps'])}</select></label><label>Project<select data-qm-expert-project>${options([['all','All relevant MACI projects'],...studyOptions()])}</select></label></div><div data-qm-expert-results>${expertView('Plain Text','all')}</div><details class="qm-card"><summary>Expert metadata retained in the existing demo</summary><p>The existing persona library contains stakeholder and organization-type labels, functions, themes, pain points and preferences. Actual expert identity, interview geography, specialty, recruitment, dated transcript passages and approved quotations have not been supplied.</p><p>“Illustrative paraphrase” is a demo summary, not a verbatim transcript quote. The existing scores below must not be treated as evidence strength or population prevalence.</p></details>`;}
  function expertView(lens,project){const rows=model.approved.filter(r=>r.method==='Qualitative'&&(project==='all'||r.project===project));const h=M.health(model,project);if(lens==='Evidence gaps')return `<div class="qm-card"><h4>Missing qualitative coverage</h4><ul>${h.coverage.filter(x=>x.needs_qual).map(x=>`<li>${esc(x.topic.name)}: approved interview passages and stakeholder coverage needed.</li>`).join('')}</ul></div>`;if(lens==='Disagreement')return h.conflicts.length?`<ul>${h.conflicts.map(([a,b])=>`<li>${esc(a.title)} / ${esc(b.title)}: coded opposing positions; compare the source passages.</li>`).join('')}</ul>`:empty('No comparable opposing approved excerpts are supplied. Different stakeholder or country contexts alone do not establish disagreement.');if(lens==='Consensus'||lens==='Outliers'||lens==='Emerging themes')return empty(`${lens} requires a reviewed coding framework, comparable interviews and collection dates. Excerpt counts alone do not establish ${lens.toLowerCase()}.`);return rows.length?`<div class="qm-grid">${rows.map(r=>`<article class="qm-card"><h4>${esc(r.title)}</h4><p>${esc(r.summary)}</p><small>${esc(r.segment)} · ${esc(r.geography)} · ${esc(r.period)}</small><p>${link(r.source,'Evidence source')} · ${esc(r.locator)}</p></article>`).join('')}</div>`:empty('No approved Quest interview excerpts are available in this scope. Public qualitative research above remains external context; the existing persona synthesis below is illustrative.');}
  function competitivePanel(){const supplier=model.public.filter(s=>s.kind==='Supplier description');return `<div class="qm-section-head"><div><span class="qm-eyebrow">MACI / COMPETITIVE CONTEXT</span><h2>Customer perceptions first. Supplier claims in context.</h2><p>Use market developments to refine research questions and explain customer findings.</p></div></div><div class="qm-chip-list">${model.context.competitive_measures.map(x=>tag(x)).join('')}</div><div class="qm-evidence-banner"><strong>Approved competitor-perception evidence: ${model.approved.filter(r=>r.topic==='perception').length} excerpts</strong><p>Awareness, consideration, stated preference and choice reasons need customer research. Published feature descriptions do not establish these measures. No market share or preference is inferred from the cards below.</p></div><details class="qm-card"><summary>Research questions linked to public developments</summary><ul><li>Which interoperability and deployment needs explain consideration of analytics providers?</li><li>Which service experiences shape perceived strengths, disadvantages and switching?</li><li>Do customer associations align with supplier messaging, and where do they differ?</li><li>Which product capabilities require a follow-up question in an existing study?</li></ul><p>These are proposed research questions, not claims about customer opinions or commitments to deliver product integrations.</p></details><div class="qm-grid">${supplier.map(sourceCard).join('')}</div>${reportControls(true)}`;}
  function reportControls(ci=false){return `<div class="qm-reports"><div><span class="qm-eyebrow">REUSABLE OUTPUTS</span><h3>Generate an evidence-bound report draft</h3><p>Source context and limitations travel with every export.</p></div><label>Report<select data-qm-report>${options(model.context.report_types.filter((_,i)=>ci?i>=13:i<13))}</select></label><label>Scope<select data-qm-report-project>${options([['all','All MACI studies'],...studyOptions()])}</select></label>${button('Download report draft','report')}</div>`;}
  function renderPartner(){const view=$('.view[data-view="copilot"]');if(!view||session().team!=='maci')return;let node=$('#qTeamAssistant');if(!node){node=document.createElement('section');node.id='qTeamAssistant';view.prepend(node);}if(node.dataset.team==='maci-research-partner-'+RELEASE){[...view.children].forEach(c=>c.classList.toggle('q-team-legacy-insights',c!==node));return;}node.className='q-team-chat qm-partner';node.dataset.team='maci-research-partner-'+RELEASE;
    const projects=model?.studies.map(p=>[p.id,p.short_name])||M.IDS.map(x=>[x,x]);
    node.innerHTML=`<div class="q-team-chat-head"><span class="qm-eyebrow">INSIGHTS ENGINE / MACI</span><h2>Quest Research & Customer Insights Partner</h2><p>Evidence fidelity first. Find prior studies, preserve context, compare segments and identify the remaining gap.</p></div><div class="q-team-chat-body"><div class="qm-filter-row"><label>Research scope<select id="qTeamChatProject">${options([['all','All relevant MACI workstreams'],...projects])}</select></label><label><input type="checkbox" id="qmIncludeDemo"> Include clearly labeled illustrative synthesis</label></div><div class="q-team-prompts">${['What have Health Systems told us about interoperability?','Compare findings across all relevant customer studies.','How do physicians and health-system executives differ?','What quantitative evidence supports this qualitative finding?','Which survey questions addressed digital experience?','Do we already have research answering this request?','Where do customer interviews contradict survey findings?'].map(q=>`<button type="button" data-team-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="qTeamPromptForm"><textarea id="qTeamPromptInput" aria-label="Research question for MACI" placeholder="Ask about a customer question, study, segment or evidence gap…" required></textarea><button type="submit" class="primary-button">Find research evidence ↗</button></form><p class="q-team-chat-source">Default: reviewed public context and locally approved excerpts. Public research is not approved Quest customer evidence. This source-bounded partner retrieves research records; a live language model is not connected.</p><div id="qTeamAnswer" class="q-team-answer" aria-live="polite" role="status" hidden></div></div>`;
    [...view.children].forEach(c=>c.classList.toggle('q-team-legacy-insights',c!==node));
  }
  function brief(r){const sections=[];const add=(title,html)=>sections.push(`<section class="qm-answer-section"><h3>${title}</h3>${html}</section>`);const internal=r.approved.length;
    add('Research answer',r.topics.length?`<p>${internal?internal+' locally approved customer excerpts match this question. Check their study context and limits below.':'The supplied repository does not contain approved Quest customer evidence sufficient to answer this question.'} ${r.public.length?'Related public research is available as context, not a finding about Quest customers.':'No reviewed public source matches the selected question and project scope.'}</p>${r.approved.map(x=>`<p><b>${esc(x.title)}:</b> ${esc(x.summary)} <small>[${esc(x.id)}; ${esc(x.locator)}]</small></p>`).join('')}${r.public.filter(x=>x.kind!=='Supplier description').map(x=>`<p><b>${esc(x.title)}:</b> ${esc(x.summary)} <small>[${esc(x.id)}]</small></p>`).join('')}`:empty('No matching topic was found. Refine the business question or name a study; no unsupported answer has been generated.'));
    add('Studies consulted',r.studies.length?`<ul>${r.studies.map(p=>`<li><b>${esc(p.short_name)}</b> · ${esc(p.research_types.join('; '))}. Delivery metadata reviewed; confidential findings are not supplied. The KBQ/topic linkage is a proposed analyst mapping.</li>`).join('')}</ul><p>${r.public.length} reviewed public sources · ${internal} locally approved customer excerpts${r.demos.length?' · illustrative synthesis included by request':''}.</p>`:empty('No study matches this scope.'));
    add('Quantitative evidence',r.quant.length?r.quant.map(s=>`<details open><summary>${esc(s.title)} · ${esc(s.sample)}</summary>${stats(s)||'<p>Closed-question context available; no response distribution extracted.</p>'}<p>${esc(s.geography)} · ${esc(s.collection_period)}</p><small>${esc(s.limitations)} [${esc(s.id)}]</small></details>`).join(''):empty('No source-backed quantitative result matches this scope. Synthetic cohort means are excluded.'));
    add('Qualitative evidence',r.qual.length?r.qual.map(s=>`<p><b>${esc(s.title)}</b>: ${esc(s.summary)}<br><small>${esc(s.method)} · ${esc(s.sample)} · ${esc(s.geography)} [${esc(s.id)}]</small></p>`).join(''):empty('No approved qualitative study passage or matching public qualitative source is available.'));
    add('Segment differences',r.public.length?`<ul>${r.public.filter(s=>s.kind!=='Supplier description').map(s=>`<li>${esc(s.population)} · ${esc(s.geography)} · ${esc(s.sample)} [${esc(s.id)}]</li>`).join('')}</ul><p>These populations are not a matched comparison. No physician-versus-executive effect size or geographic difference is inferred without a shared instrument and subgroup bases.</p>`:empty('Comparable segment-level evidence is missing.'));
    const conflict=M.conflicts(r.approved);
    add('Agreement / disagreement',`${conflict.length?'<p>Opposing coded positions exist within comparable approved records; review source passages before resolving them.</p>':'<p>No comparable contradiction is established in the approved records supplied. Shared topics and differing outcomes are not proof of consensus or conflict.</p>'}${model.context.comparability_notes.filter(n=>n.sources.some(id=>r.public.some(s=>s.id===id))).map(n=>`<p><b>${esc(n.title)}:</b> ${esc(n.reason)}</p>`).join('')}`);
    add('Evidence limitations',`<p>Project metadata shows what was commissioned and delivered, not what respondents said. Public studies use different populations, periods and methods. There is no pooled estimate, automatic significance test or invented transcript quote.</p>${r.suppliers.length?'<p>Supplier descriptions are capability and messaging context; they do not establish customer awareness, experience or preference.</p>':''}${r.demos.length?`<details><summary>Illustrative synthesis requested · ${r.demos.length} objects</summary>${r.demos.map(d=>`<p><b>${esc(d.title)}</b>: ${esc(d.body)}<small>Illustrative PMR · ${esc(d.project)} · ${esc(d.source)}</small></p>`).join('')}</details>`:''}`);
    add('Research gaps',r.topics.length?`<ul>${r.topics.map(t=>`<li><b>${esc(t.name)}:</b> ${esc(t.next_question)}<br><small>Proposed next step: ${esc(t.next_method)}. Confirm reuse of existing approved sources first.</small></li>`).join('')}</ul>`:empty('Clarify the business question, target customer group and decision to identify the gap.'));
    add('Sources',`<ol>${r.public.map(s=>`<li>${link(s.url,s.title)} · ${esc(s.id)} · ${esc(s.kind)} · published ${esc(s.published||'date not supplied')}; reviewed ${esc(s.reviewed_at)}</li>`).join('')}${r.approved.map(x=>`<li>${link(x.source,x.title)} · ${esc(x.id)} · ${esc(x.locator)} · Approved locally</li>`).join('')}${r.studies.length?`<li>${link('data/project-tracker.json','Quest delivery metadata')} · reporting date ${esc(model.tracker_date)}</li>`:''}</ol>`);
    return sections.join('');
  }
  async function answer(question,executive=false){const n=++sequence,team=session().team,panel=$(executive?'#qmExecutiveAnswer':'#qTeamAnswer');if(!question||!panel||!(team==='maci'||(executive&&team==='executive')))return;panel.hidden=false;panel.setAttribute('aria-busy','true');panel.innerHTML='<span class="q-busy-dot" aria-hidden="true"></span> Checking study context and relevant evidence…';const task=window.QuestExperience?.start('Reviewing research evidence',2);
    try{await load();window.QuestExperience?.step(task,1);if(n!==sequence||session().team!==team)return;const r=M.retrieve(model,question,$(executive?'#qmExecutiveProject':'#qTeamChatProject')?.value||'all',!!$(executive?'#qmExecutiveIncludeDemo':'#qmIncludeDemo')?.checked);lastResult=r;window.QuestExperience?.step(task,2);panel.innerHTML=`<p><b>Research question:</b> ${esc(question)}</p>${brief(r)}<div class="qm-actions">${button('Download evidence brief','brief-export')}${button('Draft research request','new-request','data-question="'+esc(question)+'"',!can('request'))}</div>`;window.QuestExperience?.enter(panel);}catch{panel.textContent='Unable to load research context. Retry the question.';}finally{panel.setAttribute('aria-busy','false');window.QuestExperience?.finish(task);}}
  function renderExecutivePartner(){
    const view=$('.view[data-view="copilot"]');if(!view||$('#qmExecutivePartner'))return;
    const el=document.createElement('details');el.id='qmExecutivePartner';el.className='q-team-chat qm-partner qm-executive-partner';
    el.innerHTML=`<summary class="q-team-chat-head"><span class="qm-eyebrow">MACI RESEARCH VIEW / EXECUTIVE ACCESS</span><h2>Quest Research & Customer Insights Partner</h2><p>Expand the evidence-first research view while retaining your complete intelligence engine.</p></summary><div class="q-team-chat-body"><div class="qm-filter-row"><label>Research scope<select id="qmExecutiveProject">${options([['all','All MACI workstreams'],...studyOptions()])}</select></label><label><input type="checkbox" id="qmExecutiveIncludeDemo"> Include labeled illustrative synthesis</label></div><form id="qmExecutivePromptForm"><textarea id="qmExecutivePromptInput" aria-label="MACI question for executive research view" placeholder="Ask about a customer question, study or evidence gap…" required></textarea><button type="submit" class="primary-button">Find research evidence ↗</button></form><p class="q-team-chat-source">Reviewed public context and locally approved customer excerpts. Public research is not approved Quest research. Source-bounded retrieval; no live language model is connected.</p><div id="qmExecutiveAnswer" class="q-team-answer" role="status" aria-live="polite" hidden></div></div>`;
    view.prepend(el);
  }
  function renderAll(force=false){if(!enabled()){ $$('.qm-module-panel,#qmExecutiveCenter,#qmExecutivePartner').forEach(x=>x.remove());return; }if(!model){load().then(()=>renderAll(true)).catch(()=>{});return;}if(session().team==='maci'){$('#qmExecutiveCenter')?.remove();$('#qmExecutivePartner')?.remove();const view=$('.view[data-view="team-dashboard"]');if(view&&(force||!view.querySelector('[data-qm-hub]')))renderHub(view);renderPartner();}else{renderExecutivePartner();const hiddenHub=$('.view[data-view="team-dashboard"] [data-qm-hub]');hiddenHub?.remove();const home=$('.view[data-view="home"]');if(home){let el=$('#qmExecutiveCenter');if(!el){el=document.createElement('details');el.id='qmExecutiveCenter';el.className='qm-executive-center';el.innerHTML='<summary>MACI Research & Customer Intelligence Center <span>Complete research visibility</span></summary><div data-qm-executive-hub></div>';home.appendChild(el);}if(force||!el.querySelector('[data-qm-hub]'))renderHub(el.querySelector('[data-qm-executive-hub]'));}}
    [['pmr',projectLibrary],['survey',surveyPanel],['experts',expertsPanel],['competitors',competitivePanel]].forEach(([route,render])=>{const view=$(`.view[data-view="${route}"]`);if(!view)return;let el=view.querySelector(':scope > .qm-module-panel');if(!el){el=document.createElement('section');el.className='qm-module-panel qm-center';el.dataset.qmModule=route;view.prepend(el);el.innerHTML=render();}else if(force)el.innerHTML=render();});
  }
  function formField(label,name,value='',type='text',required=true){return `<label>${esc(label)}<${type==='textarea'?'textarea':'input'} name="${name}" ${type==='textarea'?'':'type="'+type+'" value="'+esc(value)+'"'}${required?' required':''}>${type==='textarea'?esc(value)+'</textarea>':''}</label>`;}
  function openRequest(question=''){if(!can('request'))return;window.QuestWorkspaces.go(session().team==='executive'?'home':'team-dashboard');renderAll();if(session().team==='executive')$('#qmExecutiveCenter').open=true;activateTab('requests');const host=$('[data-qm-form-host="request"]');if(!host)return;const o=M.overlap(model,question,state().requests);
    host.innerHTML=`<form class="qm-form" data-qm-form="request"><h3>New research request</h3><p>Clarify the decision and check reusable evidence before asking for new work.</p><div class="qm-form-grid">${formField('Requestor','requestor',session().displayName||'Quest team')}${formField('Team','team','Market & Customer Insights')}${formField('Business question','question',question,'textarea')}${formField('Decision to support','decision','','textarea')}${formField('Customer group','customer')}${formField('Geography','geography')}${formField('Desired deadline','deadline','','date',false)}${formField('Research owner','owner',session().displayName||'Quest team')}<label>Priority<select name="priority">${options(['Medium','High','Low'])}</select></label>${formField('Existing evidence','existing',o.studies.map(p=>p.short_name).join('; ')||'No topic match found','textarea',false)}${formField('Potential overlap','overlap',o.note,'textarea',false)}${formField('Research gap','gap',o.gap,'textarea')}</div><div data-qm-overlap>${overlapHtml(o)}</div><div class="qm-actions">${button('Check existing evidence','check-overlap')}<button type="submit">Save request</button>${button('Cancel','cancel-form')}</div><p class="qm-form-status" role="status"></p></form>`;host.scrollIntoView?.({block:'center',behavior:'smooth'});host.querySelector('[name="question"]').focus();}
  const overlapHtml=o=>`<div class="qm-notice"><b>Potential reuse:</b> ${esc(o.studies.map(p=>p.short_name).join('; ')||'No related project found')}<p>${o.public.length} related public sources · ${o.requests.length} local requests. ${esc(o.gap)}</p><small>${esc(o.note)}</small></div>`;
  function openEvidence(){if(!can('evidence'))return;window.QuestWorkspaces.go(session().team==='executive'?'home':'team-dashboard');renderAll();if(session().team==='executive')$('#qmExecutiveCenter').open=true;activateTab('pulse');const host=$('[data-qm-form-host="evidence"]');if(!host)return;host.innerHTML=`<form class="qm-form" data-qm-form="evidence"><h3>Submit an evidence excerpt for review</h3><p>Retain the original study reference and context. The excerpt stays on this device; no private file is uploaded to GitHub.</p><div class="qm-form-grid">${formField('Evidence title','title')}<label>Research deliverable<select name="deliverable">${options(['Research finding','Survey results','Interview analysis','Study report'])}</select></label><label>Project<select name="project">${options(studyOptions())}</select></label><label>Topic<select name="topic">${options(model.context.topics.map(t=>[t.id,t.name]))}</select></label>${formField('Business question / KBQ','kbq','','textarea')}<label>Method<select name="method">${options(['Qualitative','Quantitative','Mixed methods','Secondary research'])}</select></label>${formField('Stakeholder / segment','segment')}${formField('Geography','geography')}${formField('Collection period (YYYY-MM or date range)','period')}${formField('Sample / question-level base','sample')}${formField('Finding with context','summary','','textarea')}${formField('Source URL or controlled reference','source')}${formField('Page, question or transcript passage','locator')}${formField('Evidence limitations','limitations','','textarea')}<label>Coded position<select name="stance">${options(['Not coded','Supports','Challenges','Mixed'])}</select></label></div><div class="qm-actions"><button type="submit">Submit for review</button>${button('Cancel','cancel-form')}</div><p class="qm-form-status" role="status"></p></form>`;host.querySelector('[name="title"]').focus();}
  function activateTab(id){$$('[data-qm-tab]').forEach(b=>{const active=b.dataset.qmTab===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$$('.qm-pane').forEach(p=>{p.hidden=p.id!=='qm-pane-'+id;if(!p.hidden)window.QuestExperience?.enter(p);});}
  function download(name,content,type='text/html'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function report(type,project='all'){
    const projects=model.studies.filter(p=>project==='all'||p.id===project), h=M.health(model,project);const r=M.retrieve(model,'Compare findings across all relevant customer studies.',project,false);
    const headings={ 'PMR Executive Summary':'Portfolio, evidence status and next research decisions','Study Report':'Study context and source availability','Survey Findings Report':'Published quantitative context and instrument gaps','Cross-Tab Report':'Subgroup bases and comparison limitations','Voice of Expert Synthesis':'Qualitative evidence and stakeholder context','Cross-Study Synthesis':'Reusable themes without pooled samples','Customer Segment Report':'Population and segment coverage','Journey Insights Report':'Digital, communication and workflow touchpoints','Evidence Gap Report':'Missing evidence and proposed next questions','Research Portfolio Report':'Study ownership and delivery context','Methodology Summary':'Research methods and disclosure completeness','KBQ Evidence Report':'Business-question evidence map','Agreement / Conflict / Gap Report':'Comparable evidence, tensions and missing context','Competitive Perception Report':'Customer perception availability','Quest vs. Competitor Customer Perceptions':'Customer evidence versus supplier messaging','Customer Choice Drivers':'Decision and switching evidence needs','Brand / Positioning Perception Brief':'Brand associations and positioning context','Competitive Evidence Summary':'Sourced competitive context'};
    let body=`<h2>${esc(headings[type]||type)}</h2><p>Scope: ${esc(project==='all'?'All MACI workstreams':projects[0]?.short_name||project)}. Reviewed ${model.context.reviewed_at}. Tracker reported ${model.tracker_date}.</p><p>Draft for analyst review. Public context is not approved Quest customer research. Illustrative and synthetic answers are excluded.</p>`;
    if(['Study Report','Research Portfolio Report','Methodology Summary','PMR Executive Summary'].includes(type))body+=`<table><tr><th>Study</th><th>Owner / sponsor contact</th><th>Method / status</th><th>Source gaps</th></tr>${projects.map(p=>`<tr><td>${esc(p.name)}<p>${esc(p.objective)}</p></td><td>${esc(p.owner)}<p>${esc(p.sponsor_contacts)}</p></td><td>${esc(p.research_types.join('; '))}<p>${esc(p.status_source)}</p></td><td>BU, vendor, original instrument, fieldwork period, approved deliverable locations and sample breakdown need confirmation.</td></tr>`).join('')}</table>`;
    if(type==='Research Portfolio Report')body+=`<h3>Research requests</h3>${state().requests.map(x=>`<p>${esc(x.question)} · ${esc(x.status)} · ${esc(x.owner)}</p>`).join('')||'<p>No local requests.</p>'}`;
    if(['Survey Findings Report','Cross-Tab Report'].includes(type))body+=`<h3>Published quantitative evidence</h3>${r.quant.map(s=>sourceCard(s)+stats(s)).join('')}<h3>Instrument gaps</h3><p>Response-level answers, original question wording, options, subgroup membership, geographic codes and weighting are not supplied. Synthetic means cannot support distributions or significance tests.</p>`;
    if(type==='Voice of Expert Synthesis')body+=r.qual.map(sourceCard).join('')+'<p>Approved Quest transcript passages and expert metadata are needed for an internal cross-expert synthesis.</p>';
    if(model.context.report_types.indexOf(type)>=13)body+=`<h3>Perception evidence</h3><p>${r.approved.filter(x=>x.topic==='perception').length} locally approved perception excerpts. No customer awareness, consideration, preference or switching estimate is established.</p><h3>Supplier context</h3>${r.suppliers.map(sourceCard).join('')}<h3>Proposed research</h3><p>Check unaided and aided awareness, choice reasons, perceived strengths, service experiences and switching factors in the appropriate customer groups.</p>`;
    if(['Evidence Gap Report','KBQ Evidence Report','Journey Insights Report','Customer Segment Report','Methodology Summary','Agreement / Conflict / Gap Report','PMR Executive Summary'].includes(type))body+=`<h3>Evidence coverage and next research</h3><ul>${h.coverage.map(x=>`<li><b>${esc(x.topic.name)}</b>: ${x.public_count} public sources; ${x.approved_count} approved excerpts. ${esc(x.topic.next_question)} ${esc(x.topic.next_method)}.</li>`).join('')}</ul>`;
    if(['Cross-Study Synthesis','Agreement / Conflict / Gap Report','KBQ Evidence Report','Customer Segment Report','Journey Insights Report','Competitive Evidence Summary'].includes(type))body+=brief(r);
    if(type==='Methodology Summary')body+=`<ul>${model.context.methodology_checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${link(model.context.methodology_source,'AAPOR disclosure standards')}`;
    body+=`<h2>Source register</h2><ol>${r.public.map(s=>`<li>${link(s.url,s.title)} · ${esc(s.id)} · ${esc(s.kind)} · ${esc(s.geography)} · published ${esc(s.published||'date not supplied')}</li>`).join('')}</ol><p>${link('https://atanubarik.github.io/quest-intelligence-360/data/project-tracker.json','Quest tracker metadata')} · ${esc(model.tracker_date)}</p><h2>Locally approved customer excerpts</h2>${r.approved.map(x=>`<p><b>${esc(x.title)}</b> · ${esc(x.summary)}<br>${esc(x.segment)} · ${esc(x.geography)} · ${esc(x.period)} · ${esc(x.method)}<br>${link(x.source,x.source)} · ${esc(x.locator)}<br>Limits: ${esc(x.limitations)}</p>`).join('')||'<p>No approved customer excerpts in this scope.</p>'}`;
    download(type.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.html',reportDocument(type,body));
  }
  function reportDocument(title,body){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>body{font:15px/1.6 Arial;color:#23432c;max-width:1000px;margin:40px auto;padding:20px}h1{color:#034c1f;border-bottom:5px solid #c6d52f;padding-bottom:20px}h2{margin-top:35px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd9cd;padding:12px;text-align:left;vertical-align:top}small,.qm-note{color:#56645a}.qm-source{border:1px solid #ccd9cd;border-radius:12px;padding:18px;margin:15px 0}dt{font-weight:bold}dd{margin:0 0 10px}a{color:#276930}details{display:block}summary{font-weight:bold}.qm-tag{font-size:12px;background:#edf3e5;padding:3px 8px;margin-right:6px}.qm-stat-row{margin:15px 0}.qm-stat-row strong{margin-left:20px}.qm-track{height:8px;background:#edf3e5}.qm-track i{display:block;height:8px;background:#35792a}@media print{body{margin:0}a{overflow-wrap:anywhere}section,.qm-source{break-inside:avoid}}</style></head><body><h1>${esc(title)}</h1>${body}</body></html>`;}
  function schedule(){if(queued)return;queued=true;setTimeout(()=>{queued=false;renderAll();},100);}
  function boot(){
    document.addEventListener('click',e=>{
      const tab=e.target.closest('[data-qm-tab]');if(tab){activateTab(tab.dataset.qmTab);return;}
      const b=e.target.closest('[data-qm-action]');if(!b||!enabled())return;e.preventDefault();const a=b.dataset.qmAction;
      if(a==='go'){window.QuestWorkspaces.go(b.dataset.route);if(b.dataset.route==='copilot'&&session().team==='executive'){renderExecutivePartner();$('#qmExecutivePartner').open=true;}}
      else if(a==='retry'){pending=null;load().then(()=>renderAll(true));}
      else if(a==='new-request')openRequest(b.dataset.question||'');
      else if(a==='new-evidence')openEvidence();
      else if(a==='cancel-form')b.closest('.qm-form')?.remove();
      else if(a==='ask'){window.QuestWorkspaces.go('copilot');if(session().team==='maci'){renderPartner();$('#qTeamPromptInput').value=b.dataset.question;$('#qTeamChatProject').value=b.dataset.project||'all';answer(b.dataset.question);}else{renderExecutivePartner();$('#qmExecutivePartner').open=true;$('#qmExecutivePromptInput').value=b.dataset.question;$('#qmExecutiveProject').value=b.dataset.project||'all';answer(b.dataset.question,true);}}
      else if(a==='check-overlap'){const form=b.closest('form');form.querySelector('[data-qm-overlap]').innerHTML=overlapHtml(M.overlap(model,form.elements.question.value,state().requests));}
      else if(['approve-evidence','return-evidence'].includes(a)&&can('approve')){const s=state(),r=s.evidence.find(x=>x.id===b.dataset.id);if(r&&r.status==='Pending Review'){const missing=M.validEvidence(r);if(a==='approve-evidence'&&missing.length){b.closest('article').insertAdjacentHTML('beforeend',note('Approval needs complete metadata: '+missing.join(', ')));return;}r.status=a==='approve-evidence'?'Approved':'Returned';r.reviewed_by=session().displayName||'Quest team';r.reviewed_at=new Date().toISOString();save(s);renderAll(true);}}
      else if(a==='portfolio-export'){const headers=['Project','Owner','Sponsor contacts','Business unit','Method','Status','Geography','Source'];const rows=model.studies.map(p=>[p.name,p.owner,p.sponsor_contacts,p.business_unit,p.research_types.join('; '),p.status_source,p.geography,p.source]);download('maci-research-portfolio.csv',[headers,...rows].map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv');}
      else if(a==='brief-export'&&lastResult)download('maci-research-evidence-brief.html',reportDocument('MACI Research Evidence Brief',`<p>Question: ${esc(lastResult.question)}</p>`+brief(lastResult)));
      else if(a==='report'){const host=b.closest('.qm-reports');report(host.querySelector('[data-qm-report]').value,host.querySelector('[data-qm-report-project]').value);}
      else if(a==='report-direct')report(b.dataset.report);
    });
    document.addEventListener('submit',e=>{const form=e.target;if(form.id==='qmExecutivePromptForm'){e.preventDefault();answer($('#qmExecutivePromptInput').value.trim(),true);return;}if(!form.matches('[data-qm-form]'))return;e.preventDefault();const kind=form.dataset.qmForm;if(!can(kind==='request'?'request':'evidence'))return;const record=Object.fromEntries(new FormData(form).entries());const s=state();record.id=uid();record.created_at=new Date().toISOString();record.created_by=session().displayName||'Quest team';
      if(kind==='evidence'){const missing=M.validEvidence(record);if(missing.length){form.querySelector('.qm-form-status').textContent='Complete the evidence context: '+missing.join(', ');return;}record.status='Pending Review';s.evidence.push(record);}else{if(!record.question?.trim())return;record.status='New';s.requests.push(record);}try{save(s);renderAll(true);activateTab(kind==='request'?'requests':'pulse');}catch{form.querySelector('.qm-form-status').textContent='This browser could not save the record. Export or retain your source and retry with storage enabled.';}
    });
    document.addEventListener('change',e=>{const t=e.target;if(!enabled()||!model)return;if(t.matches('[data-qm-request-status]')&&can('status')){const s=state(),r=s.requests.find(x=>x.id===t.dataset.qmRequestStatus);if(r&&model.context.request_statuses.includes(t.value)){r.status=t.value;save(s);renderAll(true);}}
      const panel=t.closest('.qm-module-panel');if(!panel)return;
      if(t.matches('[data-qm-compare],[data-qm-compare-project]'))panel.querySelector('[data-qm-comparison]').innerHTML=comparison(panel.querySelector('[data-qm-compare]').value,panel.querySelector('[data-qm-compare-project]').value);
      if(t.matches('[data-qm-survey-source]'))panel.querySelector('[data-qm-survey-chart]').innerHTML=surveyChart(t.value);
      if(t.matches('[data-qm-expert-view],[data-qm-expert-project]'))panel.querySelector('[data-qm-expert-results]').innerHTML=expertView(panel.querySelector('[data-qm-expert-view]').value,panel.querySelector('[data-qm-expert-project]').value);
    });
    document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-qm-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...tab.parentNode.querySelectorAll('[data-qm-tab]')],idx=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activateTab(tabs[next].dataset.qmTab);tabs[next].focus();});
    window.addEventListener('quest:workspace-change',()=>{sequence++;lastResult=null;renderAll(true);});
    window.addEventListener('quest:module-loaded',schedule);window.addEventListener('quest:layout-refresh',schedule);
    new MutationObserver(ms=>{if(ms.some(m=>m.addedNodes.length&&[...m.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('.view')||m.target.matches?.('.view,.content')))))schedule();}).observe(document.body,{childList:true,subtree:true});
    renderAll();
  }
  window.QuestMaci={renderHub,renderPartner,answer,load,renderAll,report,getModel:()=>model};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
